/**
 * \file    js/exportshortener.js
 * \ingroup easyurl
 * \brief   JavaScript exportshortener file for module EasyURL
 */

'use strict';

/**
 * Init exportshortener JS
 *
 * @memberof EasyURL_ExportShortener
 *
 * @since   1.1.0
 * @version 1.1.0
 *
 * @type {Object}
 */
window.easyurl.exportshortener = {};

/**
 * ExportShortener init
 *
 * @memberof EasyURL_ExportShortener
 *
 * @since   1.1.0
 * @version 1.1.0
 *
 * @returns {void}
 */
window.easyurl.exportshortener.init = function() {
  window.easyurl.exportshortener.event();
};

/**
 * ExportShortener event
 *
 * @memberof EasyURL_ExportShortener
 *
 * @since   1.1.0
 * @version 1.1.0
 *
 * @returns {void}
 */
window.easyurl.exportshortener.event = function() {
};

/**
 * ExportShortener generate export
 *
 * @memberof EasyURL_ExportShortener
 *
 * @since   1.1.0
 * @version 1.1.0
 *
 * @returns {void}
 */
window.easyurl.exportshortener.generateExport = function(nbUrl, successCount) {
  if (typeof successCount === 'undefined') successCount = nbUrl;
  let token          = window.saturne.toolbox.getToken();
  let querySeparator = window.saturne.toolbox.getQuerySeparator(document.URL);

  $.ajax({
    method: 'POST',
    url: document.URL + querySeparator + 'action=generate_export&nb_url=' + nbUrl + '&token=' + token,
    processData: false,
    contentType: false,
    success: function (resp) {
      if (successCount == nbUrl) {
          window.saturne.notice.showNotice('notice-infos', 'Success', 'Vous avez généré ' + successCount + ' / ' + nbUrl + ' URL(s) avec succès.', 'success');
      } else if (successCount > 0) {
          window.saturne.notice.showNotice('notice-infos', 'Warning', 'Génération terminée avec des erreurs : ' + successCount + ' / ' + nbUrl + ' URL(s) générées.', 'warning');
      } else {
          window.saturne.notice.showNotice('notice-infos', 'Error', 'Échec total : 0 / ' + nbUrl + ' URL(s) générées.', 'error');
      }
      window.saturne.loader.remove($('#generate-url-from .button-save'));
      $('#shortener-export-table').replaceWith($(resp).find('#shortener-export-table'));
    },
    error: function() {
      window.saturne.notice.showNotice('notice-infos', 'Error', 'ExportError', 'error');
      window.saturne.loader.remove($('#generate-url-from .button-save'));
    }
  });
};

